  [['National Register: Hinton Historic District (2004 revision)','https://npgallery.nps.gov/NRHP/GetAsset/NRHP/05000661_text'],['WVU OnView: veterans museum dedication, 1997','https://onview.lib.wvu.edu/catalog/047268'],LWV],
